"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[846],{5298:e=>{e.exports=JSON.parse('{"functions":[{"name":"Destroy","desc":"Cleans up signals, connections, tags, and backing instances for this Zone.","params":[],"returns":[],"function_type":"method","source":{"line":140,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"Relocate","desc":"Method that will Relocate the Zone to a WorldModel not in the Workspace","params":[],"returns":[{"desc":"Self Zone Object","lua_type":"Zone"}],"function_type":"method","source":{"line":150,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"SetDetection","desc":"Method to Update/Set the Default Part/TrackedItem Detection of the Zone:","params":[{"name":"DetectionCoverage","desc":"DetectionCoverages Enum or Enum Id.","lua_type":"Enum.DetectionCoverages | number"},{"name":"DetectionMode","desc":"DetectionModes Enum or Enum Id.","lua_type":"Enum.DetectionModes | number"}],"returns":[],"function_type":"method","source":{"line":160,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"SetRate","desc":"Method to Update/Set the Default Rate of the Zone:","params":[{"name":"Rate","desc":"Rates Enum or Enum Id.","lua_type":"Enum.Rates | number"}],"returns":[],"function_type":"method","source":{"line":169,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"SetSimulation","desc":"Method to Update/Set the Default Simulation (RunService Event) of the Zone:","params":[{"name":"Simulation","desc":"Simulation Enum or Enum Id.","lua_type":"Enum.Simulations | number"}],"returns":[],"function_type":"method","source":{"line":178,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"LogConfig","desc":"Method to print out all the Config Names","params":[],"returns":[],"function_type":"method","source":{"line":186,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"GetZoneParts","desc":"Method to return the array of ZoneParts","params":[],"returns":[{"desc":"","lua_type":"{BasePart}"}],"function_type":"method","source":{"line":196,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"GetZonePartHolders","desc":"Method to return the array of ZonePartHolders","params":[],"returns":[{"desc":"","lua_type":"{Instance}"}],"function_type":"method","source":{"line":206,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"GetRandomPoint","desc":"Returns a random point within this Zone\u2019s bounds.  \\nWorks with partless boxes (math) and part-backed zones (shape-aware).","params":[],"returns":[{"desc":"Point inside the zone volume","lua_type":"Vector3"}],"function_type":"method","source":{"line":217,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"GetTouchingParts","desc":"Method to return an array of all BaseParts currently touching this Zone.\\n\\nWorks for both Box-style and Part-style Zones","params":[],"returns":[{"desc":"","lua_type":"{BasePart}"}],"function_type":"method","source":{"line":229,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"Step","desc":"Method that can be called manually in a custom RunService event to step the Zone\'s detection logic\\n\\nOnly present if `ManualStepping` Config is true and the holder type is a group, if not, this method is removed","params":[{"name":"DeltaTime","desc":"RunService event DeltaTime.","lua_type":"number"}],"returns":[],"function_type":"method","source":{"line":240,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"BindToGroup","desc":"Method that will BIND the Zone to the passed Group:","params":[{"name":"GroupName","desc":"Name of the already created group to bind the Zone to","lua_type":"string"}],"returns":[],"function_type":"method","source":{"line":249,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"UnbindFromGroup","desc":"Method that will UNBIND the Zone to the passed Group:","params":[{"name":"GroupName","desc":"Name of the already created group to bind the Zone to","lua_type":"string"}],"returns":[],"function_type":"method","source":{"line":258,"path":"src/Modules/Internal/Types/ZonePublic.luau"}},{"name":"InGroup","desc":"Method to return whether the Zone is in the group or not","params":[{"name":"GroupName","desc":"Name of the group to check","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","source":{"line":269,"path":"src/Modules/Internal/Types/ZonePublic.luau"}}],"properties":[],"types":[{"name":"ZoneContainerType","desc":"Discriminates container representation (\\"Boxes\\" or \\"Instance\\" flavors)","lua_type":"(\'Part\' | \'Holder\' | \'Parts\' | \'Boxes\')","tags":["private_types"],"source":{"line":37,"path":"src/Modules/Internal/Types/ZonePrimitives.luau"}},{"name":"ZoneParts","desc":"An array of BaseParts","lua_type":"{BasePart}","tags":["private_types"],"source":{"line":46,"path":"src/Modules/Internal/Types/ZonePrimitives.luau"}}],"name":"Zone","desc":"Public facade for a single Zone created by:\\n\\n`Zoner.New(...)`, `Zoner.NewFromContainer(...)` `Zoner.NewZoneFromRegion(...)`, or `Zoner.NewZoneFromBox(...)`. \\n \\nExposes read-only state, configuration helpers, signals, and utilities while hiding internal engine details.\\n\\n**Surface**\\n- Read-only state: `Identifier`, `Active`, `Destroyed`, `Relocated`, `Paused`, `Visible`,\\n  plus detection/simulation/rate fields.\\n- Signals:\\n  - `PlayerEntered`, `PlayerExited`\\n  - `PartEntered`, `PartExited`\\n  - `LocalPlayerEntered`, `LocalPlayerExited` (client only)\\n- Configuration:\\n  - `SetDetection(DetectionCoverage, DetectionMode)`\\n  - `SetRate(Rate)`\\n  - `SetSimulation(Simulation)`\\n- Utilities:\\n  - `GetRandomPoint()` \u2014 random point from part-backed or partless box bounds\\n  - `GetTouchingParts()` \u2014 parts overlapping the zone\u2019s bounds\\n  - `Relocate()` \u2014 move content into a WorldModel for spatial queries\\n  - `LogConfig()` \u2014 configuration dump\\n- Grouping:\\n  - `BindToGroup(name)`, `UnbindFromGroup(name)`, `InGroup(name)`\\n\\n**Bounds & detection**\\n- Zones can be part-backed (Instances) or partless (CFrame/Size boxes).\\n- Uses enums supplied by `Zoner.Enum` with sensible defaults.\\n\\n**Run-context**\\n- `LocalPlayer*` signals are client-only.\\n- Methods do not yield.\\n\\n**Example**\\n```lua\\n--!strict\\nlocal Zoner = require(path.to.Zoner)\\n\\nlocal Zone: Zoner.Zone = Zoner.New(workspace.ZonePart, {\\n\\tExecution = Zoner.Enum.Execution.Parallel;\\n\\tBounds    = Zoner.Enum.Bounds.Automatic;\\n})\\n\\nZone.PlayerEntered:Connect(function(Player: Player)\\n\\tprint(player.Name, \\"Entered\\")\\nend)\\n\\nZone:SetDetection(Zoner.Enum.DetectionCoverage.Center, Zoner.Enum.DetectionMode.Point)\\n```","tags":["public_api"],"source":{"line":92,"path":"src/Modules/Internal/Types/ZonePublic.luau"}}')}}]);